INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-europe', 'Game Gear', 'Micro Machines (Europe)', '1994', 'Racing', 'Codemasters', '2', 'Racing', 'Top-down racing.', 'Win the race across household-themed tracks.', 'A legendary and addictive miniature racing port.', 'Micro Machines brings the tiny cars to the small screen. Race across breakfast tables and bathtubs in this incredibly fun and competitive 8-bit handheld racer that rewards memorization and skill.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-2---turbo-tournament-europe', 'Game Gear', 'Micro Machines 2 - Turbo Tournament (Europe)', '1994', 'Racing', 'Codemasters', '2', 'Racing', 'Top-down racing.', 'Compete in the turbo tournament across new tracks.', 'The high-speed sequel to the miniature racing hit.', 'Micro Machines 2 features more vehicles, faster gameplay, and even more creative tracks. It’s the ultimate version of the series on Game Gear, offering endless portable racing fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers---the-movie-usa-europe', 'Game Gear', 'Mighty Morphin Power Rangers - The Movie (USA, Europe)', '1995', 'Action', 'Natsume', '1', 'Movie', 'Side-scrolling beat ''em up.', 'Defeat Ivan Ooze and his army to save Angel Grove.', 'A cinematic brawler based on the feature film.', 'Mighty Morphin Power Rangers: The Movie features large sprites and intense martial arts action. Choose your favorite Ranger and battle through movie-inspired levels in this vibrant 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers-usa-europe', 'Game Gear', 'Mighty Morphin Power Rangers (USA, Europe)', '1994', 'Action', 'Natsume', '1', 'TV Series', 'Side-scrolling beat ''em up.', 'Stop Rita Repulsa and her monsters from invading.', 'The high-energy debut of the Rangers on Game Gear.', 'Mighty Morphin Power Rangers features 1v1 style combat and massive Zord battles. Experience the excitement of the TV show with smooth animation and iconic 8-bit music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mlbpa-baseball-usa', 'Game Gear', 'MLBPA Baseball (USA)', '1994', 'Sports', 'Beam Software', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your MLB team to the World Series.', 'A professional baseball sim with real player data.', 'MLBPA Baseball features officially licensed players and authentic stats. With multiple modes and realistic 8-bit mechanics, it’s a deep and rewarding baseball experience for handheld gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('moldorian---hikari-to-yami-no-sister-japan', 'Game Gear', 'Moldorian - Hikari to Yami no Sister (Japan)', '1994', 'RPG', 'Sigma Enterprises', '1', 'JRPG', 'Turn-based RPG.', 'Save your sister and stop the darkness from rising.', 'A Japanese exclusive RPG with beautiful art.', 'Moldorian: Hikari to Yami no Sister is a hidden gem on the Game Gear. Featuring a unique overhead perspective and tactical combat, it tells a compelling fantasy story with high-quality 8-bit production values.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-truck-wars-usa-europe', 'Game Gear', 'Monster Truck Wars (USA, Europe)', '1994', 'Racing', 'Zeppelin Games', '2', 'Off-road', 'Behind-the-back racing.', 'Win the championship by crushing the competition.', 'High-octane monster truck racing and destruction.', 'Monster Truck Wars brings the roar of the arena to your handheld. Navigate treacherous obstacle courses and mud tracks while managing your nitro and damage in this aggressive 8-bit racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monster-world-ii---dragon-no-wana-japan', 'Game Gear', 'Monster World II - Dragon no Wana (Japan)', '1992', 'Action RPG', 'Westone', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Break the curse by defeating the Vampire Dragon.', 'The Japanese version of Wonder Boy III: The Dragon''s Trap.', 'Monster World II is a masterpiece of non-linear design. Transform into different creatures to gain new abilities and explore a massive, interconnected 8-bit world in this definitive portable classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-japan-v33', 'Game Gear', 'Mortal Kombat (Japan) (v3.3)', '1993', 'Fighting', 'Probe Software', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat Shang Tsung and win the tournament.', 'The Japanese version of the legendary arcade brawler.', 'Mortal Kombat (Japan) features the iconic roster and fluid 8-bit combat. Execute special moves and fatalities in this technically impressive handheld conversion that captures the arcade''s dark atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-usa-europe-v26', 'Game Gear', 'Mortal Kombat (USA, Europe) (v2.6)', '1993', 'Fighting', 'Probe Software', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat Shang Tsung and win the tournament.', 'The definitive international version of the hit fighter.', 'Experience the blood-pumping action of Mortal Kombat on the go. This v2.6 release features refined controls and all the secret moves that made the original a global phenomenon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-europe', 'Game Gear', 'Mortal Kombat 3 (Europe)', '1995', 'Fighting', 'Probe Software', '2', 'Arcade', 'One-on-one fighting game.', 'Stop Shao Kahn’s invasion of Earthrealm.', 'A late-release and rare 8-bit port of the third entry.', 'Mortal Kombat 3 is a technical achievement for Game Gear. Featuring digitized-style sprites and the new "Run" mechanic, it brings the intense kombat and new characters to the small screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-world', 'Game Gear', 'Mortal Kombat II (World)', '1994', 'Fighting', 'Probe Software', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat Shao Kahn in the Outworld tournament.', 'The acclaimed sequel with more fighters and secrets.', 'Mortal Kombat II for Game Gear features improved graphics and a larger roster, including Jax and Mileena. Master the new stages and hidden fatalities in this high-quality 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-usa-europe', 'Game Gear', 'Ms. Pac-Man (USA, Europe)', '1993', 'Arcade', 'Namco', '1', 'Classic', 'Fixed-screen arcade.', 'Eat all the dots and avoid the ghosts.', 'A perfect portable version of the arcade queen.', 'Ms. Pac-Man brings the classic maze-running gameplay to Game Gear with vibrant colors. Navigate through four different maze layouts and use power pellets to turn the tables on the ghosts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazo-puyo-japan', 'Game Gear', 'Nazo Puyo (Japan)', '1993', 'Puzzle', 'Compile', '1', 'Puzzle', 'Falling block puzzle.', 'Solve specific "mission" puzzles to clear the screen.', 'A puzzle-centric spin-off of the Puyo Puyo series.', 'Nazo Puyo (Japan) focuses on logic rather than speed. Solve over 100 "Mission" stages where you must clear specific beans under set conditions in this addictive 8-bit brain-teaser.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazo-puyo-2-japan', 'Game Gear', 'Nazo Puyo 2 (Japan)', '1994', 'Puzzle', 'Compile', '1', 'Puzzle', 'Falling block puzzle.', 'Solve even more complex Puyo Puyo logic puzzles.', 'The expanded sequel to the Puyo mission series.', 'Nazo Puyo 2 (Japan) features more stages and refined puzzle mechanics. It’s a perfect "pick-up-and-play" title that rewards strategic thinking and careful placement of your Puyo beans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazo-puyo-arle-no-roux-english', 'Game Gear', 'Nazo Puyo Arle no Roux (English)', '1994', 'Puzzle', 'Compile', '1', 'Puzzle', 'Falling block puzzle.', 'Solve Arle''s puzzles to collect curry ingredients.', 'English fan-translated version of the Arle''s Roux quest.', 'Nazo Puyo Arle no Roux (English) combines Puyo puzzles with a charming RPG-lite story. Help Arle find her curry ingredients by solving logic puzzles, now fully playable in English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazo-puyo-arle-no-roux-japan', 'Game Gear', 'Nazo Puyo Arle no Roux (Japan)', '1994', 'Puzzle', 'Compile', '1', 'Puzzle', 'Falling block puzzle.', 'Solve Arle''s puzzles to collect curry ingredients.', 'The original Japanese Puyo puzzle adventure.', 'Arle no Roux features beautiful character art and a whimsical story. Navigate the map and solve "Nazo" (riddle) Puyo challenges in this high-quality and colorful 8-bit handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nazo-puyo-arle-no-roux-japan-development-edition', 'Game Gear', 'Nazo Puyo Arle no Roux (Japan) (Development Edition)', '1994', 'Puzzle', 'Compile', '1', 'Puzzle', 'Falling block puzzle.', 'Solve Arle''s puzzles to collect curry ingredients.', 'A rare development build of the Puyo puzzle quest.', 'This Development Edition of Arle no Roux offers a look at the game''s production. It’s a fascinating piece for collectors, featuring the core puzzle mechanics and charming 8-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-action-usa-europe', 'Game Gear', 'NBA Action (USA, Europe)', '1995', 'Sports', 'Sega', '2', 'Basketball', 'Sports simulation (Basketball).', 'Lead your NBA team to the playoffs.', 'A professional 5v5 basketball simulation.', 'NBA Action features officially licensed teams and players. Execute dunks, fast breaks, and strategic plays in this detailed 8-bit simulation of the professional basketball experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-japan', 'Game Gear', 'NBA Jam (Japan)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Basketball', 'Sports simulation (Basketball).', 'Win at high-flying, 2v2 arcade basketball.', 'The Japanese edition of the explosive arcade hit.', 'NBA Jam brings the "He''s On Fire!" excitement to your pocket. Featuring massive dunks and no-foul gameplay, it’s a high-energy 8-bit conversion of the legendary arcade sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-usa-europe', 'Game Gear', 'NBA Jam (USA, Europe)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Basketball', 'Sports simulation (Basketball).', 'Win at high-flying, 2v2 arcade basketball.', 'The definitive international version of NBA Jam.', 'Experience the over-the-top action of NBA Jam. Shatter backboards and perform gravity-defying moves with your favorite NBA stars in this fast-paced and addictive 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-usa-v11', 'Game Gear', 'NBA Jam (USA) (v1.1)', '1994', 'Sports', 'Iguana Entertainment', '2', 'Basketball', 'Sports simulation (Basketball).', 'Win at high-flying, 2v2 arcade basketball.', 'Updated v1.1 release of the iconic basketball game.', 'This v1.1 of NBA Jam features minor bug fixes and roster tweaks. It remains a technical showcase for the Game Gear, delivering fluid animation and frantic sports action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nba-jam-tournament-edition-usa-europe', 'Game Gear', 'NBA Jam Tournament Edition (USA, Europe)', '1995', 'Sports', 'Iguana Entertainment', '2', 'Basketball', 'Sports simulation (Basketball).', 'Win the tournament with expanded rosters and moves.', 'The definitive update to the NBA Jam series.', 'NBA Jam Tournament Edition adds new players, more power-ups, and the "Hot Spots" feature. It is the ultimate version of arcade basketball for the Game Gear’s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('neko-daisuki!-japan', 'Game Gear', 'Neko Daisuki! (Japan)', '1996', 'Puzzle', 'Sega', '1', 'Cute', 'Life simulation / Virtual pet.', 'Take care of your cats and keep them happy.', 'A charming Japanese exclusive cat simulator.', 'Neko Daisuki! (I Love Cats!) allows you to feed, play with, and raise various breeds of cats. It’s a gentle and visually cute 8-bit title that was a precursor to modern virtual pet games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-95-usa-europe', 'Game Gear', 'NFL ''95 (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'American Football', 'Sports simulation (Football).', 'Win the Super Bowl with the 1995 NFL rosters.', 'A strategic and licensed American football sim.', 'NFL ''95 brings the full 11-on-11 football experience to the handheld. Call plays and manage your team’s stats in this comprehensive 8-bit simulation of the NFL season.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-96-usa-europe', 'Game Gear', 'NFL Quarterback Club ''96 (USA, Europe)', '1995', 'Sports', 'Iguana Entertainment', '2', 'American Football', 'Sports simulation (Football).', 'Master the skills of a pro quarterback.', 'The refined ''96 edition of the football skill sim.', 'NFL Quarterback Club ''96 features updated rosters and improved AI. Focus on precision passing and play execution in this polished and challenging 8-bit portable sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nfl-quarterback-club-usa-europe', 'Game Gear', 'NFL Quarterback Club (USA, Europe)', '1994', 'Sports', 'Iguana Entertainment', '2', 'American Football', 'Sports simulation (Football).', 'Master the skills of a pro quarterback.', 'A unique football game focused on QB challenges.', 'NFL Quarterback Club features multiple modes including season play and specialized skill challenges. Experience the pressure of the gridiron in this detailed and licensed handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhl-all-star-hockey-usa-europe', 'Game Gear', 'NHL All-Star Hockey (USA, Europe)', '1995', 'Sports', 'Electronic Arts', '2', 'Ice Hockey', 'Sports simulation (Hockey).', 'Win the Stanley Cup with NHL stars.', 'A fast-paced and licensed ice hockey simulation.', 'NHL All-Star Hockey features all the teams and players from the era. Master the one-timers and defensive checks in this high-energy 8-bit conversion of the beautiful game on ice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nhl-hockey-usa-europe', 'Game Gear', 'NHL Hockey (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '2', 'Ice Hockey', 'Sports simulation (Hockey).', 'Outscore the opponent in a full hockey season.', 'The first professional NHL game for the Game Gear.', 'NHL Hockey brings the intensity of the rink to the small screen. Featuring smooth skating and realistic 8-bit physics, it’s a solid and competitive sports title for hockey fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden-japan', 'Game Gear', 'Ninja Gaiden (Japan)', '1991', 'Action', 'Tecmo', '1', 'Platform', 'Side-scrolling action.', 'Defeat the dark forces and recover the Dragon Sword.', 'The Japanese version of the handheld ninja exclusive.', 'Ninja Gaiden (Japan) is an original 8-bit adventure. Follow Ryu Hayabusa through cinematic cutscenes and intense platforming levels that are unique to the Game Gear hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden-usa-europe', 'Game Gear', 'Ninja Gaiden (USA, Europe)', '1991', 'Action', 'Tecmo', '1', 'Platform', 'Side-scrolling action.', 'Defeat the dark forces and recover the Dragon Sword.', 'A high-speed, handheld-exclusive ninja masterpiece.', 'Ninja Gaiden for Game Gear is a must-play. Not a port of the NES game, it features unique levels, brand new bosses, and the series'' signature fast-paced wall-jumping action in vibrant color.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninku-japan', 'Game Gear', 'Ninku (Japan)', '1995', 'Action', 'Sega', '1', 'Anime', 'One-on-one fighting game.', 'Win the tournament using Ninku martial arts.', 'A Japanese exclusive fighter based on the anime.', 'Ninku features a unique cast of characters with elemental powers. Experience fluid 1v1 combat and impressive 8-bit character sprites in this faithful adaptation of the popular manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninku-2---tenkuuryuu-e-no-michi-japan', 'Game Gear', 'Ninku 2 - Tenkuuryuu e no Michi (Japan)', '1995', 'Action', 'Sega', '1', 'Anime', 'Tactical strategy / Adventure.', 'Travel to the Heavenly Dragon and defeat the enemy.', 'The sequel to the Ninku fighting adventure.', 'Ninku 2 expands the series with deeper story elements and more tactical combat. Explore a fantasy world and master the Ninku fighting styles in this polished Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninku-gaiden---hiroyuki-daikatsugeki-japan', 'Game Gear', 'Ninku Gaiden - Hiroyuki Daikatsugeki (Japan)', '1996', 'Action', 'Sega', '1', 'Anime', 'Mini-game collection.', 'Win various challenges as the penguin Hiroyuki.', 'A quirky spin-off featuring the Ninku mascot.', 'Ninku Gaiden: Hiroyuki Daikatsugeki is a collection of fun and fast-paced mini-games. It captures the humor and art style of the series in a vibrant and accessible portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nomo-hideo-no-world-series-baseball-japan', 'Game Gear', 'Nomo Hideo no World Series Baseball (Japan)', '1995', 'Sports', 'Sega', '1', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to victory in the World Series.', 'A Japanese exclusive baseball sim featuring Hideo Nomo.', 'Nomo Hideo no World Series Baseball offers realistic 8-bit mechanics and professional stats. Celebrate the career of the legendary pitcher in this detailed and competitive sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-gold-europe-enfrdeesitnlptsv-v11', 'Game Gear', 'Olympic Gold (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv) (v1.1)', '1994', 'Sports', 'Sega', '4', 'Olympics', 'Multi-event sports simulation.', 'Win the gold medal in the Barcelona ''92 Games.', 'The refined v1.1 of the official Olympic game.', 'Olympic Gold (v1.1) features seven athletic events including 100m sprint and archery. With smooth animation and a high competitive curve, it’s one of the most polished sports titles for the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-gold-japan-usa-enfrdeesitnlptsv', 'Game Gear', 'Olympic Gold (Japan, USA) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1994', 'Sports', 'Sega', '4', 'Olympics', 'Multi-event sports simulation.', 'Win the gold medal in the Barcelona ''92 Games.', 'The worldwide release of the hit Olympic sim.', 'Experience the thrill of the 1994 Olympics on your handheld. Master the timing and button-mashing required to break world records in this comprehensive and officially licensed 8-bit sports collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ottifants-the-europe-enfrdeesit', 'Game Gear', 'Ottifants, The (Europe) (En,Fr,De,Es,It)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find your family and avoid the hazards.', 'A charming European adventure based on the German comic.', 'The Ottifants features Bruno the elephant in a quest filled with puzzles and platforming. Its vibrant 8-bit graphics and creative level design make it a hidden gem for fans of character-driven platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-run-japan', 'Game Gear', 'Out Run (Japan)', '1991', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Reach the finish line before time expires.', 'A faithful portable port of the legendary arcade racer.', 'Out Run (Japan) brings the blue skies and Ferrari Testarossa to the small screen. Featuring the iconic soundtrack and branching paths, it’s a high-speed nostalgia trip that looks great in color.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-run-europa-usa-europe', 'Game Gear', 'Out Run Europa (USA, Europe)', '1991', 'Racing', 'Sega', '1', 'Arcade', 'Vehicular action / Racing.', 'Stop the criminal organization across Europe.', 'A cinematic spin-off with cars, boats, and bikes.', 'Out Run Europa shifts the focus to mission-based driving. Evade the police and take down enemies using various vehicles in this gritty and action-packed 8-bit expansion of the Out Run brand.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-attack-usa-europe', 'Game Gear', 'Pac-Attack (USA, Europe)', '1993', 'Puzzle', 'Namco', '1', 'Arcade', 'Falling block puzzle.', 'Clear the screen of ghosts using Pac-Man.', 'A clever "Pac-themed" twist on the Tetris formula.', 'Pac-Attack combines classic puzzle mechanics with Pac-Man''s ghost-eating hunger. Strategize your block placement to clear lines and unleash Pac-Man in this addictive and colorful handheld puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-in-time-proto', 'Game Gear', 'Pac-In-Time (Proto)', '1993', 'Puzzle', 'Kalisto', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect all items to open the door to the next level.', 'An unreleased prototype of the clever puzzle-platformer.', 'Pac-In-Time (Proto) offers a rare look at a "lost" Game Gear title. Use different abilities like a rope or hammer to navigate levels in this unique 8-bit take on the Pac-Man universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-man-usa-europe', 'Game Gear', 'Pac-Man (USA, Europe)', '1991', 'Arcade', 'Namco', '1', 'Classic', 'Fixed-screen arcade.', 'Eat all the dots and avoid the four ghosts.', 'A perfect, pocket-sized version of the arcade original.', 'Pac-Man on Game Gear is a faithful conversion of the 1980 legend. It features the classic maze and ghost AI, providing an endlessly replayable 8-bit arcade experience on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('panzer-dragoon-mini-japan', 'Game Gear', 'Panzer Dragoon Mini (Japan)', '1996', 'Shooter', 'Sega', '1', 'Anime', 'Behind-the-back rail shooter.', 'Destroy the enemy fleet while riding your dragon.', 'A rare handheld-exclusive entry in the Panzer series.', 'Panzer Dragoon Mini features "chibi" style dragons but maintains the series'' intense shooting action. Dodge enemy fire and take down massive bosses in this unique and visually impressive Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-usa-europe', 'Game Gear', 'Paperboy (USA, Europe)', '1991', 'Action', 'Atari Games', '1', 'Arcade', 'Isometric action.', 'Deliver all newspapers while avoiding obstacles.', 'A frantic and challenging arcade conversion.', 'Paperboy brings the neighborhood chaos to your handheld. Navigate suburban streets filled with runaway tires, aggressive dogs, and breakable windows in this classic 8-bit test of reflexes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-ii-usa-europe', 'Game Gear', 'Paperboy II (USA, Europe)', '1992', 'Action', 'Tengen', '1', 'Arcade', 'Isometric action.', 'Deliver papers to new neighborhoods and avoid hazards.', 'The expanded sequel with more variety and characters.', 'Paperboy II features the choice of a paperboy or papergirl. With more obstacles and bonus levels, it expands the classic arcade formula for a deeper 8-bit portable challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pengo-japan', 'Game Gear', 'Pengo (Japan)', '1990', 'Arcade', 'Sega', '1', 'Classic', 'Fixed-screen action puzzle.', 'Crush the Sno-Bees by sliding ice blocks.', 'The Japanese version of the quirky Sega arcade hit.', 'Pengo features the brave penguin in a maze of ice. Use your environment to trap and defeat enemies in this vibrant and addictive 8-bit puzzle-actioner.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pengo-usa-europe', 'Game Gear', 'Pengo (USA, Europe)', '1990', 'Arcade', 'Sega', '1', 'Classic', 'Fixed-screen action puzzle.', 'Crush the Sno-Bees by sliding ice blocks.', 'The international release of the ice-block brawler.', 'Guide Pengo through 8-bit frozen mazes in this Western version. With its catchy music and fast-paced gameplay, it remains a cult classic for fans of old-school Sega arcade titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pet-club-inu-daisuki!-japan', 'Game Gear', 'Pet Club Inu Daisuki! (Japan)', '1995', 'Simulation', 'Sega', '1', 'Casual', 'Life simulation / Virtual pet.', 'Raise your dog and keep it healthy and happy.', 'A charming Japanese exclusive dog simulator.', 'Pet Club: Inu Daisuki! allows you to choose and care for various dog breeds. Feed, walk, and train your pet in this cute and colorful precursor to the modern virtual pet genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pete-sampras-tennis-europe', 'Game Gear', 'Pete Sampras Tennis (Europe)', '1994', 'Sports', 'Sega', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the tournament and reach the top of the rankings.', 'A professional tennis sim endorsed by the legend.', 'Pete Sampras Tennis features fast-paced, fluid gameplay and multiple court types. Master the serve and volley to defeat tough AI opponents in this polished 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-96-usa-europe', 'Game Gear', 'PGA Tour 96 (USA, Europe)', '1995', 'Sports', 'Electronic Arts', '1', 'Golf', 'Sports simulation (Golf).', 'Win the PGA Tour championship on pro courses.', 'The final and most refined 8-bit PGA simulation.', 'PGA Tour 96 offers updated stats and smooth 8-bit visuals. With its realistic approach to wind, club selection, and green reading, it’s a deep and rewarding portable golf experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-usa-europe', 'Game Gear', 'PGA Tour Golf (USA, Europe)', '1994', 'Sports', 'Electronic Arts', '1', 'Golf', 'Sports simulation (Golf).', 'Win the PGA Tour championship on pro courses.', 'A foundational and realistic portable golf sim.', 'PGA Tour Golf brings the professional links to the Game Gear. Featuring real courses and a technical swing mechanic, it provides a high-quality sports challenge for golf fans on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-usa-v11', 'Game Gear', 'PGA Tour Golf (USA) (v1.1)', '1994', 'Sports', 'Electronic Arts', '1', 'Golf', 'Sports simulation (Golf).', 'Win the PGA Tour championship on pro courses.', 'Updated v1.1 release with refined mechanics.', 'This v1.1 of PGA Tour Golf features minor gameplay balance tweaks. Experience the pressure of the pro circuit with improved 8-bit physics and challenging course layouts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-ii-usa-europe', 'Game Gear', 'PGA Tour Golf II (USA, Europe)', '1996', 'Sports', 'Electronic Arts', '1', 'Golf', 'Sports simulation (Golf).', 'Compete in the tour with more courses and features.', 'The expansive sequel to the pro golf hit.', 'PGA Tour Golf II features more courses and improved graphics. It builds on the original''s solid foundation to deliver one of the most comprehensive sports simulations on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-adventure-japan', 'Game Gear', 'Phantasy Star Adventure (Japan)', '1992', 'RPG', 'Sega', '1', 'Fantasy', 'Menu-driven adventure.', 'Solve the mystery on the Motavia planet.', 'A Japanese exclusive adventure spin-off of the RPG saga.', 'Phantasy Star Adventure is a unique, text-heavy quest. Solve puzzles and interact with characters in the PS universe using an intuitive menu system in this rare and story-rich 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-adventure-japan-en-by-aeon-genesis-v10', 'Game Gear', 'Phantasy Star Adventure (Japan) [En by Aeon Genesis v1.0]', '1992', 'RPG', 'Sega', '1', 'Fantasy', 'Menu-driven adventure.', 'Solve the mystery on the Motavia planet.', 'English fan-translated version of the PS spin-off.', 'This English translation allows Western fans to finally play Phantasy Star Adventure. Experience the deep lore and character interactions of the Motavia mystery in full English on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-gaiden-japan', 'Game Gear', 'Phantasy Star Gaiden (Japan)', '1994', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Explore the world and stop the rising darkness.', 'A Japanese exclusive prequel to the original Phantasy Star.', 'Phantasy Star Gaiden features a new set of heroes and a traditional overhead perspective. It is an essential piece of lore for fans of the series, featuring classic 8-bit RPG combat and exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-gaiden-japan-en-by-magic-destiny-v1012', 'Game Gear', 'Phantasy Star Gaiden (Japan) [En by Magic Destiny v1.012]', '1994', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Explore the world and stop the rising darkness.', 'English fan-translated version of the PS prequel.', 'This fan translation brings Phantasy Star Gaiden to the West. Embark on an epic 8-bit quest to uncover the origins of Alis and the star system in this deep and story-driven handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-gaiden-japan-en-by-magic-destiny-v1012-wide-font', 'Game Gear', 'Phantasy Star Gaiden (Japan) [En by Magic Destiny v1.012] (Wide Font)', '1994', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Explore the world and stop the rising darkness.', 'English version with an improved, readable wide font.', 'This "Wide Font" version of Phantasy Star Gaiden (English) offers a more comfortable reading experience while exploring the game''s massive story and tactical turn-based battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantom-2040-usa-europe', 'Game Gear', 'Phantom 2040 (USA, Europe)', '1995', 'Action', 'Virgin Interactive', '1', 'Sci-Fi', 'Side-scrolling action platformer.', 'Stop the conspiracy and save the city of the future.', 'A dark, atmospheric brawler based on the animated series.', 'Phantom 2040 features non-linear exploration and multiple endings. Use a variety of high-tech weapons to navigate a cyberpunk world in this visually stunning and deep 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pinball-dreams-usa', 'Game Gear', 'Pinball Dreams (USA)', '1992', 'Pinball', 'Spidersoft', '1', 'Simulation', 'Pinball simulation.', 'Achieve the high score across multiple tables.', 'A high-quality port of the classic Amiga pinball hit.', 'Pinball Dreams features realistic physics and four distinct table themes: Ignition, Steel Wheel, Beat Box, and Nightmare. It’s one of the most mechanically sound pinball titles on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pocket-jansou-japan', 'Game Gear', 'Pocket Jansou (Japan)', '1994', 'Tabletop', 'Sega', '1', 'Mahjong', 'Mahjong simulation.', 'Defeat opponents in a game of professional Mahjong.', 'A portable and high-stakes Japanese Mahjong sim.', 'Pocket Jansou provides a deep challenge for Mahjong fans. With clear 8-bit tiles and multiple AI opponents, it’s a solid and strategic title designed for long gaming sessions on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poker-faced-pauls-blackjack-usa-europe', 'Game Gear', 'Poker Faced Paul''s Blackjack (USA, Europe)', '1993', 'Casino', 'Adrenalin Interactive', '1', 'Cards', 'Card game simulation.', 'Win big at the Blackjack table.', 'A specialized part of the "Poker Faced Paul" collection.', 'Poker Faced Paul''s Blackjack offers a realistic 8-bit casino experience. Master your betting strategy and try to beat the dealer in this clean and accessible handheld card simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poker-faced-pauls-gin-usa-europe', 'Game Gear', 'Poker Faced Paul''s Gin (USA, Europe)', '1993', 'Casino', 'Adrenalin Interactive', '1', 'Cards', 'Card game simulation.', 'Outscore your opponent in a game of Gin Rummy.', 'A portable and competitive card game sim.', 'Poker Faced Paul''s Gin brings the classic card game to the Game Gear. Featuring smart AI and clear visuals, it’s a perfect title for those looking for a strategic and relaxing handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poker-faced-pauls-poker-usa-europe', 'Game Gear', 'Poker Faced Paul''s Poker (USA, Europe)', '1993', 'Casino', 'Adrenalin Interactive', '1', 'Cards', 'Card game simulation.', 'Win the tournament in a high-stakes Poker match.', 'A comprehensive and challenging portable Poker sim.', 'Poker Faced Paul''s Poker features various styles and betting modes. Test your bluffing skills against the computer in this detailed and well-presented 8-bit card simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poker-faced-pauls-solitaire-usa-europe', 'Game Gear', 'Poker Faced Paul''s Solitaire (USA, Europe)', '1993', 'Casino', 'Adrenalin Interactive', '1', 'Cards', 'Card game simulation.', 'Clear the board in several Solitaire variations.', 'The ultimate portable Solitaire collection.', 'Poker Faced Paul''s Solitaire features multiple modes including Klondike and Spider. It’s the perfect "pick-up-and-play" title for the Game Gear, offering relaxing and addictive puzzle-card fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pop-breaker-japan', 'Game Gear', 'Pop Breaker (Japan)', '1991', 'Puzzle', 'Sega', '1', 'Arcade', 'Falling block puzzle.', 'Clear the screen by matching colored balls.', 'A vibrant Japanese exclusive color-matching puzzler.', 'Pop Breaker is a high-energy puzzle game for the Game Gear. Featuring cute characters and fast-paced gameplay, you must strategically clear the board in this colorful 8-bit handheld gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('popeye-no-beach-volleyball-japan', 'Game Gear', 'Popeye no Beach Volleyball (Japan)', '1994', 'Sports', 'Sega', '2', 'Cartoon', 'Sports simulation.', 'Win the beach volleyball tournament as Popeye.', 'A sun-soaked sports title starring the famous sailor.', 'Popeye no Beach Volleyball (Japan) features fun, arcade-style sports action. Master your serves and spikes on the sand in this charming and visually bright Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-strike-ii-japan-europe', 'Game Gear', 'Power Strike II (Japan, Europe)', '1993', 'Shooter', 'Sega', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the sky pirates and their mechanical fleet.', 'One of the most technically impressive 8-bit shooters.', 'Power Strike II (GG Aleste II) is a masterpiece by Compile. Featuring blistering speed, incredible weapon variety, and massive bosses, it is a must-play technical showcase for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('predator-2-usa-europe', 'Game Gear', 'Predator 2 (USA, Europe)', '1992', 'Action', 'Teeny Weeny Games', '1', 'Military', 'Side-scrolling action.', 'Rescue hostages and defeat the Predator in the city.', 'A gritty urban shooter based on the sci-fi sequel.', 'Predator 2 tasks you with navigating dangerous city streets while being hunted. Use a variety of high-tech weapons to clear drug gangs and survive the ultimate hunter in this intense 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('primal-rage-usa-europe', 'Game Gear', 'Primal Rage (USA, Europe)', '1994', 'Fighting', 'Atari Games', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat the other beast-gods to rule Urth.', 'A portable version of the prehistoric fighting hit.', 'Primal Rage brings giant dinosaur combat to your pocket. Featuring digitized-style sprites and special moves, it captures the unique dark atmosphere of the arcade original on 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-usa-europe', 'Game Gear', 'Prince of Persia (USA, Europe)', '1992', 'Platform', 'Broderbund', '1', 'Cinematic', 'Side-scrolling platformer.', 'Rescue the Princess within the 60-minute time limit.', 'A smooth and cinematic puzzle-platformer classic.', 'Prince of Persia on Game Gear features incredibly fluid rotoscoped animation. Navigate deadly traps and engage in sword duels in this faithful and challenging 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-usa-europe-beta', 'Game Gear', 'Prince of Persia (USA, Europe) (Beta)', '1992', 'Platform', 'Broderbund', '1', 'Cinematic', 'Side-scrolling platformer.', 'Rescue the Princess within the 60-minute time limit.', 'Beta version of the cinematic platforming epic.', 'This Prince of Persia Beta offers a rare look at the development of the 8-bit port. Test the physics and the iconic timer-based gameplay in this early handheld build.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-91-the-japan', 'Game Gear', 'Pro Yakyuu ''91, The (Japan)', '1991', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to the Japanese championship.', 'A detailed 1991 Japanese professional baseball sim.', 'The Pro Yakyuu ''91 offers deep stats and realistic 8-bit mechanics. Experience the high-stakes world of Japanese pro baseball with smooth pitching and batting gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-gg-league-94-japan', 'Game Gear', 'Pro Yakyuu GG League ''94 (Japan)', '1994', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the league title with updated 1994 rosters.', 'Refined and fast-paced Japanese baseball action.', 'Pro Yakyuu GG League ''94 features improved graphics and tighter controls. It’s a solid and competitive sports simulation that shines on the Game Gear’s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-gg-league-japan', 'Game Gear', 'Pro Yakyuu GG League (Japan)', '1993', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the league title with the pro Japanese teams.', 'The foundational entry in the GG League series.', 'Pro Yakyuu GG League brings arcade-style baseball to the handheld. With its accessible controls and vibrant sprites, it’s a perfect "pick-up-and-play" sports title for the move.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psychic-world-usa-europe', 'Game Gear', 'Psychic World (USA, Europe)', '1991', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action.', 'Rescue your friend using ESP and psychic powers.', 'A high-quality action game with RPG elements.', 'Psychic World features Lucia, a heroine who uses different elemental psychic shots. Navigate through beautifully drawn levels and upgrade your powers in this polished 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psychic-world-usa-europe-v11', 'Game Gear', 'Psychic World (USA, Europe) (v1.1)', '1991', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action.', 'Rescue your friend using ESP and psychic powers.', 'Updated v1.1 of the psychic-powered adventure.', 'Experience refined gameplay in Psychic World (v1.1). This version features minor tweaks to the difficulty and mechanics, making it the definitive way to play this 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putt-&-putter-japan', 'Game Gear', 'Putt & Putter (Japan)', '1992', 'Puzzle', 'Sega', '2', 'Casual', 'Isometric mini-golf.', 'Sink the ball in the hole while avoiding hazards.', 'A quirky and colorful golf-puzzle hybrid.', 'Putt & Putter (Japan) features creative courses and tricky obstacles. It’s a fun and strategic take on mini-golf that rewards precision and planning on the 8-bit screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putt-&-putter-usa-europe', 'Game Gear', 'Putt & Putter (USA, Europe)', '1992', 'Puzzle', 'Sega', '2', 'Casual', 'Isometric mini-golf.', 'Sink the ball in the hole while avoiding hazards.', 'The international release of the golf-puzzle hit.', 'Challenge yourself with the clever level design of Putt & Putter. This version offers addictive "puzzle-golf" gameplay that is perfect for short portable sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-japan', 'Game Gear', 'Puyo Puyo (Japan)', '1993', 'Puzzle', 'Compile', '2', 'Cute', 'Falling block puzzle.', 'Match four "Puyos" of the same color to clear them.', 'The original Japanese block-matching sensation.', 'Puyo Puyo on Game Gear is an addictive test of speed and logic. Chain together massive combos to bury your opponent in "garbage" in this quintessential 8-bit puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puyo-puyo-2-japan', 'Game Gear', 'Puyo Puyo 2 (Japan)', '1994', 'Puzzle', 'Compile', '2', 'Cute', 'Falling block puzzle.', 'Defeat rivals in the tower to become the champion.', 'The expanded sequel with new characters and modes.', 'Puyo Puyo 2 (Puyo Puyo Tsu) adds the "Offsetting" mechanic, deepening the strategy. Featuring vibrant art and voice clips, it is one of the best puzzle games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-and-action-tanto-r-japan', 'Game Gear', 'Puzzle and Action Tanto-R (Japan)', '1994', 'Puzzle', 'Sega', '2', 'Arcade', 'Mini-game collection.', 'Complete a series of wacky challenges to win.', 'A portable version of the iconic puzzle-arcade hit.', 'Tanto-R features dozens of hilarious and fast-paced mini-games. Test your reflexes, memory, and logic in this vibrant Japanese exclusive that perfectly captures Sega’s quirky spirit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('puzzle-bobble-japan', 'Game Gear', 'Puzzle Bobble (Japan)', '1994', 'Puzzle', 'Taito', '2', 'Cute', 'Bubble-matching puzzle.', 'Clear the screen by matching three or more bubbles.', 'The Japanese version of the addictive puzzle hit.', 'Puzzle Bobble brings the color-matching sensation to your pocket. Aim your launcher and clear the board in this high-pressure, endlessly replayable 8-bit puzzle classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quest-for-the-shaven-yak-starring-ren-hoek-&-stimpy-usa-europe', 'Game Gear', 'Quest for the Shaven Yak Starring Ren Hoek & Stimpy (USA, Europe)', '1993', 'Platform', 'Realtime Associates', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the legendary Shaven Yak with the Nick duo.', 'A wacky and gross-out Looney adventure.', 'Quest for the Shaven Yak features the iconic humor of Ren & Stimpy. Navigate bizarre levels and use your unique abilities in this colorful and challenging 8-bit platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quiz-gear-fight!!-the-japan', 'Game Gear', 'Quiz Gear Fight!!, The (Japan)', '1992', 'Quiz', 'Sega', '2', 'Arcade', 'Quiz / Fighting.', 'Defeat enemies by answering trivia questions.', 'A unique Japanese hybrid of quiz and combat.', 'The Quiz Gear Fight!! tasks you with using your knowledge to win battles. It’s a charming and visually distinct title that offers a refreshing twist on the 8-bit fighting genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rbi-baseball-94-usa-europe', 'Game Gear', 'R.B.I. Baseball ''94 (USA, Europe)', '1994', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the World Series with professional rosters.', 'A fast and accessible portable baseball sim.', 'R.B.I. Baseball ''94 features officially licensed players and authentic stats. With its smooth animation and strategic depth, it’s a top-tier sports experience for Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rc-grand-prix-usa-europe', 'Game Gear', 'R.C. Grand Prix (USA, Europe)', '1992', 'Racing', 'Absolute Entertainment', '1', 'Arcade', 'Isometric racing.', 'Win races and upgrade your car to the top tier.', 'A challenging and high-speed overhead racer.', 'R.C. Grand Prix features a unique perspective and deep car customization. Master the tight corners and manage your budget in this technically impressive 8-bit racing sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rastan-saga-japan', 'Game Gear', 'Rastan Saga (Japan)', '1991', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling action.', 'Defeat the dragon and rescue the princess.', 'A dark and atmospheric barbarian brawler.', 'Rastan Saga (Japan) brings the arcade''s gritty combat to the handheld. Use your sword and various items to battle mythical beasts in this difficult and visually moody 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('revenge-of-drancon-usa', 'Game Gear', 'Revenge of Drancon (USA)', '1990', 'Action', 'Sage''s Creations', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Rescue Minnie Mouse from the witch Mizrabel.', 'The North American name for Castle of Illusion.', 'Revenge of Drancon is the same legendary Mickey Mouse adventure under a different title. Experience the pinnacle of 8-bit platforming with stunning graphics and perfect controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('riddick-bowe-boxing-japan', 'Game Gear', 'Riddick Bowe Boxing (Japan)', '1993', 'Sports', 'Micronics', '2', 'Boxing', 'Sports simulation (Boxing).', 'Knock out rivals to become the world champion.', 'The Japanese version of the pro-boxing sim.', 'Riddick Bowe Boxing features large, detailed sprites and an intense behind-the-back perspective. Master your defense and power punches to climb the rankings in this 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('riddick-bowe-boxing-usa', 'Game Gear', 'Riddick Bowe Boxing (USA)', '1993', 'Sports', 'Micronics', '2', 'Boxing', 'Sports simulation (Boxing).', 'Knock out rivals to become the world champion.', 'A gritty and hard-hitting 8-bit boxing sim.', 'Experience the intensity of the ring with Riddick Bowe. Featuring a deep career mode and smooth animation, it’s one of the most mechanically sound boxing games on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rise-of-the-robots-usa-europe', 'Game Gear', 'Rise of the Robots (USA, Europe)', '1995', 'Fighting', 'Mirage Studios', '1', 'Sci-Fi', 'One-on-one fighting game.', 'Win the tournament to save the future.', 'A futuristic fighter with high-tech robots.', 'Rise of the Robots features impressive pre-rendered style sprites for the time. Battle through a series of metallic rivals in this visually unique and atmospheric 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ristar---the-shooting-star-usa-europe', 'Game Gear', 'Ristar - The Shooting Star (USA, Europe)', '1995', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the solar system by grabbing and throwing.', 'A visual and mechanical masterpiece for Game Gear.', 'Ristar is one of the best games on the system. Instead of jumping, use Ristar’s extendable arms to climb, swing, and headbutt enemies in this incredibly colorful and creative 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-usa-europe', 'Game Gear', 'Road Rash (USA, Europe)', '1992', 'Racing', 'Electronic Arts', '1', 'Arcade', 'Behind-the-back racing.', 'Win illegal bike races and outrun the cops.', 'A fast, fluid, and violent motorcycle racer.', 'Road Rash on Game Gear is a technical marvel. Punch and kick your rivals at high speeds while navigating traffic in this incredibly addictive and responsive 8-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-3-usa-europe', 'Game Gear', 'RoboCop 3 (USA, Europe)', '1992', 'Action', 'Ocean Software', '1', 'Sci-Fi', 'Side-scrolling action shooter.', 'Protect the innocent and stop OCP''s corruption.', 'A gritty action game based on the sci-fi sequel.', 'RoboCop 3 features multiple gameplay styles, including side-scrolling combat and flying sequences. Use your high-tech weaponry to bring justice to a dark 8-bit Detroit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-versus-the-terminator-usa-europe', 'Game Gear', 'RoboCop versus The Terminator (USA, Europe)', '1994', 'Action', 'Virgin Interactive', '1', 'Sci-Fi', 'Side-scrolling action.', 'Prevent the future where Skynet rules the world.', 'A gritty crossover with intense 8-bit firepower.', 'RoboCop versus The Terminator delivers explosive action. Fight through waves of Terminators and corrupt OCP forces in this visually dark and challenging handheld shooter based on the comic series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('roll-chan:-mini-world', 'Game Gear', 'Roll-chan: Mini World', '2023', 'Platform', 'Homebrew', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat the Robot Masters as Roll.', 'A charming fan-made "hack" of Mega Man.', 'Roll-chan: Mini World swaps the iconic hero for his sister, Roll. Experience the tight platforming and boss battles of the original Game Gear Mega Man with a fresh, adorable character skin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('royal-stone---hirakareshi-toki-no-tobira-japan', 'Game Gear', 'Royal Stone - Hirakareshi Toki no Tobira (Japan)', '1992', 'RPG', 'Sega', '1', 'Fantasy', 'Tactical strategy RPG.', 'Lead Eva on a quest to restore her honor and kingdom.', 'One of the most beautiful and deep RPGs on the system.', 'Royal Stone is a technical marvel featuring large, detailed combat sprites and a deep tactical system. It’s the spiritual successor to Crystal Warriors, offering a mature story and polished 8-bit strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ryuukyuu-japan', 'Game Gear', 'Ryuukyuu (Japan)', '1991', 'Puzzle', 'Sega', '1', 'Abstract', 'Tile-matching puzzle.', 'Clear the board by matching traditional tiles.', 'A relaxing and strategic Japanese puzzle game.', 'Ryuukyuu brings the atmosphere of traditional tile games to the Game Gear. Use logic and foresight to clear the screen in this culturally rich and addictive 8-bit handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ss-lucifer---man-overboard!-europe', 'Game Gear', 'S.S. Lucifer - Man Overboard! (Europe)', '1991', 'Action', 'Codemasters', '1', 'Arcade', 'Side-scrolling puzzle.', 'Save the passengers from the sinking ocean liner.', 'A unique rescue-based platformer.', 'S.S. Lucifer: Man Overboard! (known as Sink or Swim elsewhere) tasks you with clearing paths and operating machinery to guide survivors to safety in this clever and colorful 8-bit puzzle game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-shodown-usa-europe', 'Game Gear', 'Samurai Shodown (USA, Europe)', '1994', 'Fighting', 'Takara', '2', 'Arcade', 'One-on-one fighting game.', 'Win the tournament using ancient weapon arts.', 'A high-quality port of SNK''s weapon-based fighter.', 'Samurai Shodown features the iconic cast, including Haohmaru and Nakoruru. Experience the tension of blade-to-blade combat and powerful special moves in this impressive 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('samurai-spirits-japan', 'Game Gear', 'Samurai Spirits (Japan)', '1994', 'Fighting', 'Takara', '2', 'Arcade', 'One-on-one fighting game.', 'Win the tournament using ancient weapon arts.', 'The original Japanese version of the SNK brawler.', 'Samurai Spirits (Japan) captures the arcade''s style with large character portraits and fluid 1v1 combat. It remains one of the most mechanically sound fighting games on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scratch-golf-japan', 'Game Gear', 'Scratch Golf (Japan)', '1994', 'Sports', 'Sega', '2', 'Golf', 'Sports simulation (Golf).', 'Win the tournament and improve your handicap.', 'A precise and detailed Japanese golf sim.', 'Scratch Golf features realistic physics and a variety of courses. Manage your club selection and account for the elements in this polished and relaxing 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam---winners-history-japan', 'Game Gear', 'SD Gundam - Winner''s History (Japan)', '1995', 'Strategy', 'BEC', '1', 'Mecha', 'Turn-based strategy.', 'Command mobile suits to win the interstellar war.', 'A deep tactical Gundam sim with beautiful art.', 'SD Gundam: Winner''s History features iconic mechs in strategic grid-based battles. Utilize different units and terrain to defeat the enemy forces in this polished Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sd-gundam---winners-history-japan-en-by-gaijin-v099', 'Game Gear', 'SD Gundam - Winner''s History (Japan) [En by Gaijin v0.99]', '1995', 'Strategy', 'BEC', '1', 'Mecha', 'Turn-based strategy.', 'Command mobile suits to win the interstellar war.', 'English fan-translated version of the Gundam sim.', 'This English version of Winner''s History allows fans to fully understand the deep tactical menus and story of the SD Gundam universe on the Game Gear’s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sega-game-pack-4-in-1-europe', 'Game Gear', 'Sega Game Pack 4 in 1 (Europe)', '1992', 'Compilation', 'Sega', '2', 'Various', 'Multi-game collection.', 'High scores in Columns, Soccer, Rally, and Tennis.', 'A diverse 4-in-1 bundle for quick gaming bursts.', 'Sega Game Pack features four classic genres in one cartridge. Whether you want a quick puzzle or a sports match, it’s the ultimate "pick-up-and-play" companion for the portable system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sensible-soccer-europe', 'Game Gear', 'Sensible Soccer (Europe)', '1993', 'Sports', 'Sensible Software', '2', 'Soccer', 'Top-down sports sim.', 'Lead your team to victory in a global tournament.', 'A fast-paced and fluid 8-bit soccer classic.', 'Sensible Soccer features the series'' signature zoomed-out view and lightning-fast controls. Master the curve-shot and lead your favorite club to glory in this highly-regarded portable sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadam-crusader---harukanaru-oukoku-japan', 'Game Gear', 'Shadam Crusader - Harukanaru Oukoku (Japan)', '1992', 'Action', 'Sega', '1', 'Fantasy', 'Turn-based RPG.', 'Travel across the desert to reclaim the kingdom.', 'An Arabian-themed RPG with beautiful visuals.', 'Shadam Crusader (known as Defenders of Oasis in the West) is a storytelling masterpiece. Explore ancient ruins and engage in tactical battles in this visually stunning 8-bit handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai-ii-japan', 'Game Gear', 'Shanghai II (Japan)', '1994', 'Puzzle', 'Sunsoft', '2', 'Classic', 'Mahjong puzzle.', 'Match tiles to clear the board within the time limit.', 'A polished portable version of the classic Shanghai.', 'Shanghai II features multiple tile sets and challenging layouts. It’s a perfect test of observation and logic that shines on the Game Gear’s high-contrast color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shaq-fu-usa-europe', 'Game Gear', 'Shaq Fu (USA, Europe)', '1995', 'Fighting', 'Delphine Software', '2', 'Arcade', 'One-on-one fighting game.', 'Rescue a boy and defeat the evil Kaile.', 'A martial arts fighter starring the basketball legend.', 'Shaq Fu features large, fluidly animated sprites and a unique mystical setting. Battle through a variety of supernatural opponents in this colorful and quirky 8-bit handheld brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shikinjou-japan', 'Game Gear', 'Shikinjou (Japan)', '1992', 'Action', 'Sega', '1', 'Fantasy', 'Sliding tile puzzle.', 'Move the blocks to clear the path and escape.', 'A brain-teasing Japanese logic puzzle game.', 'Shikinjou tasks you with manipulating tiles within a confined space. It’s a challenging and addictive title that rewards patience and planning, perfect for the dedicated puzzle gamer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force-gaiden---ensei-jashin-no-kuni-e-japan', 'Game Gear', 'Shining Force Gaiden - Ensei, Jashin no Kuni e (Japan)', '1992', 'Strategy', 'Sega', '1', 'Tactical RPG', 'Tactical strategy RPG.', 'Defeat the forces of Iom and save the kingdom.', 'The first portable entry in the legendary saga.', 'Shining Force Gaiden features the series'' iconic turn-based grid combat and cinematic battle animations. Lead your army through a deep story in this essential 8-bit strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force-gaiden---final-conflict-japan', 'Game Gear', 'Shining Force Gaiden - Final Conflict (Japan)', '1993', 'Strategy', 'Sega', '1', 'Tactical RPG', 'Tactical strategy RPG.', 'Stop the resurrection of the ancient evil.', 'The epic conclusion to the Game Gear Gaiden trilogy.', 'Final Conflict bridges the story between the first and second main games. It features refined mechanics and some of the best 8-bit tactical combat ever produced for a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force-gaiden---final-conflict-japan-en-by-sfcentral-v20060707', 'Game Gear', 'Shining Force Gaiden - Final Conflict (Japan) [En by SFCentral v20060707]', '1993', 'Strategy', 'Sega', '1', 'Tactical RPG', 'Tactical strategy RPG.', 'Stop the resurrection of the ancient evil.', 'English fan-translated finale of the Gaiden trilogy.', 'This English version of Final Conflict allows Western fans to experience the lore-heavy conclusion of the saga. Engage in massive tactical battles and follow the story in full English.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force-gaiden-ii---jashin-no-kakusei-japan', 'Game Gear', 'Shining Force Gaiden II - Jashin no Kakusei (Japan)', '1993', 'Strategy', 'Sega', '1', 'Tactical RPG', 'Tactical strategy RPG.', 'Assemble the Shining Force to stop the god of evil.', 'The acclaimed sequel to the first portable Gaiden.', 'Shining Force Gaiden II (The Sword of Hajya) features an expanded roster and more complex battle scenarios. It is widely considered one of the finest strategy games in the 8-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shining-force-ii---the-sword-of-hajya-usa-europe', 'Game Gear', 'Shining Force II - The Sword of Hajya (USA, Europe)', '1994', 'Strategy', 'Sega', '1', 'Tactical RPG', 'Tactical strategy RPG.', 'Assemble the Shining Force to stop the god of evil.', 'The international release of the strategy masterpiece.', 'Shining Force II: The Sword of Hajya brings the epic console experience to your pocket. Master tactical positioning and level up your heroes in this definitive handheld RPG adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('side-pocket-usa', 'Game Gear', 'Side Pocket (USA)', '1992', 'Sports', 'Probe Software', '2', 'Arcade', 'Sports simulation (Pool).', 'Clear the table and win the billiards tournament.', 'A stylish and realistic 8-bit pool simulation.', 'Side Pocket features smooth ball physics and a cool jazz-inspired atmosphere. Master trick shots and compete in various modes in this polished and addictive handheld sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---bart-vs-the-space-mutants-usa-europe', 'Game Gear', 'Simpsons, The - Bart vs. The Space Mutants (USA, Europe)', '1991', 'Platform', 'Imagineering', '1', 'Cartoon', 'Side-scrolling platformer.', 'Stop the aliens from spray-painting the world purple.', 'A creative Simpsons adventure with unique mechanics.', 'Bart vs. The Space Mutants tasks you with using gadgets to reveal hidden aliens. It’s a challenging and visually vibrant movie/TV tie-in with a focus on exploration and puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---bart-vs-the-world-usa-europe', 'Game Gear', 'Simpsons, The - Bart vs. The World (USA, Europe)', '1992', 'Platform', 'Imagineering', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue the Simpsons family from a global tour.', 'A massive world-spanning Simpsons adventure.', 'Bart vs. The World features varied mini-games and platforming levels across the globe. Use Bart’s costumes and skills to defeat Krusty’s rivals in this colorful 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('skweek-japan', 'Game Gear', 'Skweek (Japan)', '1991', 'Puzzle', 'Loriciels', '1', 'Cute', 'Top-down puzzle action.', 'Paint the floor of each level to move forward.', 'A fast-paced and colorful Japanese puzzle port.', 'Skweek features a cute hero in a quest to recolor the world. Dodge enemies and manage power-ups in this addictive and visually bright 8-bit handheld arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slider-usa-europe', 'Game Gear', 'Slider (USA, Europe)', '1991', 'Puzzle', 'Loriciels', '1', 'Arcade', 'Isometric puzzle.', 'Slide the tiles to guide the light to the exit.', 'A challenging and unique light-based logic game.', 'Slider (known as Skweek in Europe) requires fast thinking and precise movement. Navigate hazard-filled floors to clear each level in this polished and creative 8-bit puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smurfs-the-europe-enfrdees', 'Game Gear', 'Smurfs, The (Europe) (En,Fr,De,Es)', '1994', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue the captured Smurfs from Gargamel.', 'A beautiful and difficult European platformer.', 'The Smurfs features vibrant graphics that perfectly capture the cartoon’s art style. Navigate through forests and caves in this high-quality and challenging 8-bit handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solitaire-funpak-usa-europe', 'Game Gear', 'Solitaire Funpak (USA, Europe)', '1992', 'Card', 'GameTek', '1', 'Casino', 'Card game collection.', 'Play several variations of the classic Solitaire.', 'The ultimate card game companion for Game Gear.', 'Solitaire Funpak offers a variety of modes including Klondike and FreeCell. With its clean interface and portable nature, it’s the perfect title for a relaxing gaming session on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solitaire-poker-usa-europe', 'Game Gear', 'Solitaire Poker (USA, Europe)', '1992', 'Card', 'GameTek', '1', 'Casino', 'Card game / Poker.', 'Combine Solitaire and Poker into a unique challenge.', 'A creative hybrid of two classic card genres.', 'Solitaire Poker tasks you with building poker hands within a solitaire layout. It’s a deep and strategic title that provides a fresh twist on traditional 8-bit handheld card games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-&-tails-japan', 'Game Gear', 'Sonic & Tails (Japan)', '1993', 'Action', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the animals and find the Chaos Emeralds.', 'The Japanese version of Sonic Chaos.', 'Sonic & Tails features two playable characters with unique moves. Fly with Tails or speed through levels with Sonic in this vibrant and high-speed 8-bit handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-&-tails-2-japan', 'Game Gear', 'Sonic & Tails 2 (Japan)', '1994', 'Action', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat Dr. Robotnik and his robotic army.', 'The Japanese version of Sonic the Hedgehog Triple Trouble.', 'Sonic & Tails 2 features large sprites and impressive vehicle segments. It is one of the most technically advanced Sonic titles on the Game Gear, offering pure 8-bit speed and color.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-world', 'Game Gear', 'Sonic Blast (World)', '1996', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Stop Dr. Robotnik and find the Chaos Emeralds.', 'A visually unique Sonic with pre-rendered graphics.', 'Sonic Blast pushes the Game Gear''s limits with its pseudo-3D look. Play as Sonic or Knuckles and blast through colorful zones in this late-release handheld adventure that offers a distinct 8-bit visual style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-chaos-usa-europe', 'Game Gear', 'Sonic Chaos (USA, Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Recover the Chaos Emeralds and defeat Robotnik.', 'The first 8-bit Sonic game featuring Tails as playable.', 'Sonic Chaos delivers high-speed action and creative level design. Use Tails’ flight or Sonic’s new Strike Dash to navigate vibrant zones in this highly-regarded 8-bit portable classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-drift-japan', 'Game Gear', 'Sonic Drift (Japan)', '1994', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Win the Grand Prix and outpace your rivals.', 'The first-ever Sonic kart racing experience.', 'Sonic Drift (Japan) features iconic characters in a high-speed tournament. Master the power-ups and tight corners in this colorful 8-bit racer that paved the way for future Sega racing hits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-drift-japan-sample', 'Game Gear', 'Sonic Drift (Japan) (Sample)', '1994', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Win the Grand Prix and outpace your rivals.', 'A rare "Sample" or demo build of the racing hit.', 'This Sonic Drift (Sample) offers a fascinating look at the game''s pre-release state. Experience the core racing mechanics and 8-bit scaling tech that defined Sonic’s first handheld kart outing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-drift-2-japan', 'Game Gear', 'Sonic Drift 2 (Japan)', '1995', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Become the champion of the Blue, Yellow, and Red GPs.', 'The expanded and refined handheld racing sequel.', 'Sonic Drift 2 features more characters, including Metal Sonic and Knuckles. With improved handling and more diverse tracks, it’s the definitive 8-bit kart racer for the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-labyrinth-usa-europe', 'Game Gear', 'Sonic Labyrinth (USA, Europe)', '1995', 'Action', 'Minato Giken', '1', 'Cartoon', 'Isometric puzzle-platformer.', 'Navigate the mazes and find the exit keys.', 'A unique and challenging "spin" on Sonic gameplay.', 'Sonic Labyrinth tasks you with exploring 3D-style labyrinths under a time limit. Use the Spin Dash to navigate hazards and solve puzzles in this quirky and colorful handheld exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-spinball-usa-europe', 'Game Gear', 'Sonic Spinball (USA, Europe)', '1993', 'Action', 'Sega', '1', 'Arcade', 'Pinball-action hybrid.', 'Free the animals and stop the Veg-O-Fortress.', 'A high-energy pinball adventure starring Sonic.', 'Sonic Spinball brings the 16-bit hit to your pocket. Navigate massive 8-bit pinball tables as Sonic, using momentum and flippers to defeat bosses in this intense and unique platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog---triple-trouble-usa-europe', 'Game Gear', 'Sonic The Hedgehog - Triple Trouble (USA, Europe)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Stop Robotnik and Knuckles from taking the emeralds.', 'Widely considered the best Sonic game on the system.', 'Sonic The Hedgehog: Triple Trouble is a technical masterpiece. Featuring large zones, vehicle segments, and incredible boss fights, it’s the pinnacle of 8-bit Sonic platforming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-japan', 'Game Gear', 'Sonic The Hedgehog (Japan)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the animals and defeat Dr. Robotnik.', 'The Japanese version of Sonic''s portable debut.', 'Sonic The Hedgehog (Japan) offers a unique set of levels distinct from the Genesis version. Explore the Bridge and Jungle Zones in this vibrant and perfectly-scaled 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-world-proto', 'Game Gear', 'Sonic The Hedgehog (World) (Proto)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the animals and defeat Dr. Robotnik.', 'A rare prototype of the original 8-bit Sonic.', 'This Sonic The Hedgehog Proto features early level layouts and subtle differences from the final release. A must-see for historians of Sega''s iconic blue mascot on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-world-v11', 'Game Gear', 'Sonic The Hedgehog (World) (v1.1)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the animals and defeat Dr. Robotnik.', 'The refined v1.1 release of the 8-bit debut.', 'Experience the fastest 8-bit hero in Sonic The Hedgehog (v1.1). This version features minor bug fixes and remains a foundational title that defines the Game Gear''s color capabilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-2-world', 'Game Gear', 'Sonic The Hedgehog 2 (World)', '1992', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Tails from the clutches of Dr. Robotnik.', 'A notoriously difficult and high-speed sequel.', 'Sonic The Hedgehog 2 features intense vehicle sequences and challenging boss fights. Navigate high-tech bases and sky-high zones in this fast-paced and visually impressive 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('soukoban-japan', 'Game Gear', 'Soukoban (Japan)', '1989', 'Puzzle', 'Thinking Rabbit', '1', 'Abstract', 'Top-down puzzle.', 'Push all the boxes into their designated slots.', 'The classic Japanese port of the legendary warehouse puzzle.', 'Soukoban challenges your logic and spatial awareness. Every move counts in this brain-teasing 8-bit title, offering dozens of levels that reward patience and strategic planning.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-harrier-usa-europe', 'Game Gear', 'Space Harrier (USA, Europe)', '1991', 'Shooter', 'Sega', '1', 'Arcade', 'Behind-the-back rail shooter.', 'Destroy the dragon invaders and save the world.', 'A stunning and fluid port of the arcade legend.', 'Space Harrier on Game Gear is a technical marvel. Featuring fast scaling and intense shooting action, guide your jet-clad hero through surreal landscapes in this impressive 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---return-of-the-sinister-six-usa-europe', 'Game Gear', 'Spider-Man - Return of the Sinister Six (USA, Europe)', '1992', 'Action', 'Teeny Weeny Games', '1', 'Superhero', 'Side-scrolling action.', 'Defeat the Six and stop Mysterio''s sinister plan.', 'A gritty and challenging Spider-Man adventure.', 'Return of the Sinister Six features iconic villains like Sandman and Hobgoblin. Use your web-slinging and wall-climbing skills to save New York in this atmospheric 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-and-the-x-men-in-arcades-revenge-usa-europe', 'Game Gear', 'Spider-Man and the X-Men in Arcade''s Revenge (USA, Europe)', '1993', 'Action', 'Software Creations', '1', 'Superhero', 'Multi-genre action.', 'Survive Arcade''s deadly games and rescue the X-Men.', 'A high-stakes crossover featuring Marvel''s finest.', 'Arcade''s Revenge tasks Spider-Man with saving Storm, Wolverine, and Cyclops. Each hero has unique levels, offering varied gameplay styles in this difficult and colorful 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-vs-the-kingpin-usa-europe', 'Game Gear', 'Spider-Man vs. The Kingpin (USA, Europe)', '1993', 'Action', 'Technopop', '1', 'Superhero', 'Side-scrolling action platformer.', 'Stop the Kingpin and defuse the city''s bomb.', 'A cinematic brawler based on the hit comic/show.', 'Spider-Man vs. The Kingpin features branching paths and intense boss battles. Use Spidey''s agility to navigate through New York and defeat the criminal underworld in this polished 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spirou-europe-proto', 'Game Gear', 'Spirou (Europe) (Proto)', '1993', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find Fantasio and stop the evil plot.', 'A rare prototype of the famous French comic hero.', 'Spirou (Proto) features beautiful 8-bit art and smooth platforming. Explore diverse locations and use gadgets in this unreleased handheld adventure that captures the charm of the BD series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-illustrated-championship-football-&-baseball-usa-europe', 'Game Gear', 'Sports Illustrated Championship Football & Baseball (USA, Europe)', '1994', 'Sports', 'Sports Illustrated', '2', 'Simulation', 'Sports simulation.', 'Win the championship in both football and baseball.', 'A 2-in-1 sports bundle featuring pro-style play.', 'Sports Illustrated brings the magazine''s authority to the Game Gear. Featuring detailed stats and realistic 8-bit mechanics, it’s a comprehensive challenge for dual-sport enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-trivia---championship-edition-usa-europe', 'Game Gear', 'Sports Trivia - Championship Edition (USA, Europe)', '1994', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Answer thousands of sports questions to win.', 'The definitive trivia challenge for sports fans.', 'Sports Trivia: Championship Edition features expanded categories and more clues. Test your knowledge of baseball, football, and more in this detailed and competitive 8-bit simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-trivia-usa-europe', 'Game Gear', 'Sports Trivia (USA, Europe)', '1991', 'Trivia', 'GameTek', '2', 'Quiz', 'Quiz / Trivia.', 'Answer thousands of sports questions to win.', 'A portable test of your athletic knowledge.', 'Sports Trivia on Game Gear is perfect for quick brain-training on the go. Featuring a variety of difficulty levels, it captures the tension of a TV game show in 8-bit handheld form.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek---the-next-generation-usa-europe', 'Game Gear', 'Star Trek - The Next Generation (USA, Europe)', '1993', 'Action', 'Beam Software', '1', 'Sci-Fi', 'Tactical simulation / Strategy.', 'Lead the Enterprise on various diplomatic and combat missions.', 'A deep and strategic Star Trek experience.', 'Star Trek: TNG features bridge management and tactical ship-to-ship combat. Solve interstellar mysteries and maintain your systems in this detailed 8-bit handheld simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-trek-generations---beyond-the-nexus-usa-europe', 'Game Gear', 'Star Trek Generations - Beyond the Nexus (USA, Europe)', '1994', 'Action', 'Probe Software', '1', 'Sci-Fi', 'Action-adventure / Puzzle.', 'Stop Soran and save the Nexus from destruction.', 'A cinematic adventure based on the feature film.', 'Generations: Beyond the Nexus blends ship combat, isometric exploration, and puzzles. Experience the meeting of Kirk and Picard in this visually impressive and story-driven 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-europe', 'Game Gear', 'Star Wars (Europe)', '1992', 'Action', 'Ubisoft', '1', 'Sci-Fi', 'Side-scrolling action.', 'Destroy the Death Star and save the galaxy.', 'The European release of the epic space opera.', 'Star Wars brings the thrill of the films to your pocket. Play as Luke Skywalker, pilot an X-Wing, and fight through the Empire''s forces in this polished and difficult 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-usa', 'Game Gear', 'Star Wars (USA)', '1992', 'Action', 'Ubisoft', '1', 'Sci-Fi', 'Side-scrolling action.', 'Destroy the Death Star and save the galaxy.', 'The North American edition of the Star Wars quest.', 'Experience the iconic journey from Tatooine to the Death Star. Featuring classic music and challenging platforming, this US version is a high-quality action game for fans of the Force.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stargate-usa-europe', 'Game Gear', 'Stargate (USA, Europe)', '1994', 'Action', 'Probe Software', '1', 'Sci-Fi', 'Side-scrolling shooter / Puzzle.', 'Unlock the Stargate and defeat the alien threat.', 'A tactical action game based on the sci-fi movie.', 'Stargate tasks you with navigating alien worlds and using high-tech explosives. Solve environmental puzzles and eliminate Ra''s forces in this atmospheric and unique 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('streets-of-rage-world', 'Game Gear', 'Streets of Rage (World)', '1991', 'Action', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Clean up the city streets and defeat Mr. X.', 'A legendary brawler in portable form.', 'Streets of Rage (World) features the iconic trio and incredible 8-bit music. Punch and kick your way through the Syndicate’s army in this technically impressive and gritty handheld port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('streets-of-rage-ii-world', 'Game Gear', 'Streets of Rage II (World)', '1992', 'Action', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue Adam and take down the Syndicate once more.', 'One of the best brawlers ever made for a handheld.', 'Streets of Rage II is a masterpiece on the Game Gear. Featuring large sprites, new moves, and a legendary Yuzo Koshiro soundtrack, it brings the arcade experience to your pocket with amazing style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-battletank-usa', 'Game Gear', 'Super Battletank (USA)', '1994', 'Simulation', 'Improve', '1', 'Military', 'Isometric vehicular combat.', 'Defeat the enemy army with your advanced tank.', 'A tactical and destructive military simulator.', 'Super Battletank features 3D-style cockpit views and intense battlefield action. Manage your fuel and ammo while hunting down targets in this impressive pseudo-3D 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-columns-japan', 'Game Gear', 'Super Columns (Japan)', '1995', 'Puzzle', 'Sega', '2', 'Arcade', 'Falling block puzzle.', 'Match colored jewels to clear the screen.', 'The vibrant handheld evolution of the Columns saga.', 'Super Columns adds new power-ups and competitive modes to the classic formula. With its flashy 8-bit visuals and addictive logic gameplay, it’s the definitive puzzle experience for the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-columns-usa', 'Game Gear', 'Super Columns (USA)', '1995', 'Puzzle', 'Sega', '2', 'Arcade', 'Falling block puzzle.', 'Match colored jewels to clear the screen.', 'The North American version of the super-charged puzzler.', 'Super Columns (USA) brings the classic Sega jewel-matching gameplay to the forefront. Featuring new "Magic Jewels" and high-energy competitive modes, it’s a vibrant and addictive 8-bit handheld masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-golf-japan', 'Game Gear', 'Super Golf (Japan)', '1994', 'Sports', 'Sega', '1', 'Golf', 'Sports simulation (Golf).', 'Win the tournament on 18-hole professional courses.', 'A polished Japanese exclusive golf simulation.', 'Super Golf offers detailed environmental physics and a clean interface. Master your swing and manage the wind across beautiful green fairways in this relaxing yet challenging 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-kick-off-japan', 'Game Gear', 'Super Kick Off (Japan)', '1994', 'Sports', 'Dino Dini', '2', 'Soccer', 'Sports simulation (Soccer).', 'Outscore your opponent in a fast-paced match.', 'The Japanese edition of the legendary soccer sim.', 'Super Kick Off brings the classic overhead soccer action to your pocket. Featuring smooth movement and a technical dribbling system, it’s a high-stakes 8-bit simulation of the world''s favorite game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-momotarou-dentetsu-iii-japan', 'Game Gear', 'Super Momotarou Dentetsu III (Japan)', '1995', 'Board', 'Game Arts', '1', 'Strategy', 'Digital board game / Strategy.', 'Become the wealthiest railroad mogul in Japan.', 'A massive and colorful Japanese exclusive board game.', 'Super Momotarou Dentetsu III features charming character art and deep economic strategy. Travel across Japan by train, buying properties and avoiding bad luck in this vibrant 8-bit multiplayer hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-monaco-gp-japan', 'Game Gear', 'Super Monaco GP (Japan)', '1992', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Win the F1 World Championship.', 'The Japanese version of the iconic F1 racer.', 'Super Monaco GP delivers high-speed open-wheel racing. Featuring real tracks and a technical pit-stop mechanic, it’s a challenging and responsive title for handheld racing enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-monaco-gp-usa-europe', 'Game Gear', 'Super Monaco GP (USA, Europe)', '1992', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Win the F1 World Championship.', 'The definitive international F1 racing simulation.', 'Experience the prestige of Monaco on the small screen. With its impressive scaling and fast-paced gameplay, this 8-bit classic remains one of the best racing titles on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road-usa-europe', 'Game Gear', 'Super Off Road (USA, Europe)', '1991', 'Racing', 'Angel Studios', '2', 'Arcade', 'Isometric racing.', 'Win the dirt track circuit and upgrade your truck.', 'High-speed, four-player off-road racing action.', 'Super Off Road features the legendary Ivan "Ironman" Stewart''s trucks. Earn money to upgrade your tires and nitro in this frantic and addictive 8-bit overhead racing port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-return-of-the-jedi-usa-europe', 'Game Gear', 'Super Return of the Jedi (USA, Europe)', '1992', 'Action', 'Sculptured Software', '1', 'Sci-Fi', 'Side-scrolling action.', 'Defeat the Emperor and save the galaxy.', 'A cinematic brawler based on the Star Wars finale.', 'Super Return of the Jedi features diverse gameplay including speeder bike chases and lightsaber combat. Experience the epic conclusion of the original trilogy in vibrant 8-bit handheld color.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-tv-world', 'Game Gear', 'Super Smash T.V. (World)', '1992', 'Action', 'Beam Software', '2', 'Arcade', 'Top-down twin-stick shooter.', 'Survive the game show and win big prizes.', 'A frantic and gore-filled arcade shooting hit.', 'Super Smash T.V. tasks you with surviving waves of enemies in a futuristic arena. Collect power-ups and cash in this high-intensity 8-bit port that pushes the system’s action limits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-space-invaders-usa-europe', 'Game Gear', 'Super Space Invaders (USA, Europe)', '1992', 'Shooter', 'Taito', '1', 'Arcade', 'Fixed-screen shooter.', 'Defeat the descending alien invaders.', 'A modern and vibrant update of the arcade legend.', 'Super Space Invaders features colorful graphics and new boss patterns. It’s a perfect handheld evolution of the classic formula, offering fast-paced 8-bit shooting fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman---the-man-of-steel-europe', 'Game Gear', 'Superman - The Man of Steel (Europe)', '1992', 'Action', 'Graftgold', '1', 'Superhero', 'Side-scrolling action.', 'Save Metropolis from the forces of Brainiac.', 'A heroic action game starring the Man of Steel.', 'Superman features flight, super-strength, and heat vision. Battle through urban levels to stop a global threat in this visually impressive and challenging European-exclusive 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('surf-ninjas-usa', 'Game Gear', 'Surf Ninjas (USA)', '1993', 'Action', 'Sims', '1', 'Cartoon', 'Side-scrolling beat ''em up.', 'Defeat the evil Colonel Chi to save the island.', 'A brawler based on the 90s martial arts movie.', 'Surf Ninjas features large sprites and unique character abilities. Use your combat skills and humor to navigate hazardous levels in this colorful and quirky 8-bit movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sylvan-tale-japan', 'Game Gear', 'Sylvan Tale (Japan)', '1995', 'RPG', 'Sega', '1', 'Fantasy', 'Action-RPG.', 'Save the world of Sylvatia by finding the six seeds.', 'A stunning and deep Japanese exclusive Action-RPG.', 'Sylvan Tale is often compared to Zelda for its exploration and item-based progression. Featuring incredible graphics and a rich world, it is a hidden gem of the 8-bit era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sylvan-tale-japan-en-by-aeon-genesis-v101', 'Game Gear', 'Sylvan Tale (Japan) [En by Aeon Genesis v1.01]', '1995', 'RPG', 'Sega', '1', 'Fantasy', 'Action-RPG.', 'Save the world of Sylvatia by finding the six seeds.', 'English fan-translated version of the RPG masterpiece.', 'This English version of Sylvan Tale allows Western players to fully enjoy the epic story and complex puzzles of this high-quality 8-bit handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('t2---the-arcade-game-usa-europe', 'Game Gear', 'T2 - The Arcade Game (USA, Europe)', '1993', 'Action', 'Probe Software', '1', 'Sci-Fi', 'Behind-the-back shooter.', 'Destroy the Terminator army and save the resistance.', 'A high-stakes rail shooter based on the arcade hit.', 'T2: The Arcade Game brings the cinematic shooting action to the Game Gear. Use your crosshair to eliminate Terminators in this fast-paced and technically impressive 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tails-adventures-japan-usa-enja', 'Game Gear', 'Tails Adventures (Japan, USA) (En,Ja)', '1995', 'Action', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer / Metroidvania.', 'Collect gadgets and items to defeat Battle Bird.', 'A deep and exploratory adventure starring Tails.', 'Tails Adventures features RPG elements and inventory management. Use various bombs and the remote-controlled Sea Fox to explore the island in this high-quality 8-bit spinoff.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tails-no-skypatrol-japan', 'Game Gear', 'Tails no Skypatrol (Japan)', '1995', 'Shooter', 'Sega', '1', 'Cartoon', 'Side-scrolling shooter.', 'Stop Witchcart by flying through obstacle courses.', 'A unique and fast-paced flying puzzle-actioner.', 'Tails no Skypatrol (Japan) tasks you with maintaining flight while dodging hazards. It’s a colorful and charming exclusive that showcases Tails'' solo flying skills in a creative way.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taisen-mahjong-haopai-japan', 'Game Gear', 'Taisen Mahjong HaoPai (Japan)', '1992', 'Mahjong', 'Sega', '2', 'Traditional', 'Mahjong simulation.', 'Defeat opponents in professional Mahjong matches.', 'A strategic and high-stakes Japanese card game.', 'Taisen Mahjong HaoPai offers clear visuals and smart AI. Perfect your Mahjong strategy in this polished 8-bit simulation, designed for deep thinking on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taisen-mahjong-haopai-2-japan', 'Game Gear', 'Taisen Mahjong HaoPai 2 (Japan)', '1993', 'Mahjong', 'Sega', '2', 'Traditional', 'Mahjong simulation.', 'Win the tournament against even tougher rivals.', 'The refined sequel to the Japanese Mahjong hit.', 'HaoPai 2 features updated graphics and more diverse AI personalities. It provides a comprehensive and challenging Mahjong experience for the Game Gear’s color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taisen-gata-daisenryaku-g-japan', 'Game Gear', 'Taisen-gata Daisenryaku G (Japan)', '1995', 'Strategy', 'Sega', '1', 'War', 'Turn-based strategy.', 'Command your army to capture the enemy capital.', 'A deep and tactical Japanese military simulation.', 'Taisen-gata Daisenryaku G features realistic units and complex terrain modifiers. It’s a hardcore strategy title that rewards careful planning and tactical execution on the 8-bit screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taito-chase-hq-japan', 'Game Gear', 'Taito Chase H.Q. (Japan)', '1992', 'Racing', 'Taito', '1', 'Arcade', 'Behind-the-back racing.', 'Chase down and ram criminal vehicles into submission.', 'High-speed police pursuit based on the arcade classic.', 'Taito Chase H.Q. (Japan) brings the thrill of the chase to your handheld. Navigate traffic and use your nitro to catch the villains in this fast-paced and atmospheric 8-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tale-spin-usa-europe', 'Game Gear', 'Tale Spin (USA, Europe)', '1991', 'Platform', 'Sims', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate the skies and find the lost cargo.', 'A charming Disney adventure starring Baloo.', 'Tale Spin features unique shooting mechanics and vibrant graphics. Fly through varied levels and defeat sky pirates in this high-quality 8-bit handheld movie/TV tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tama-&-friends-sanchoume-kouen---tamalympic-japan', 'Game Gear', 'Tama & Friends Sanchoume Kouen - Tamalympic (Japan)', '1995', 'Mini-Games', 'Sega', '1', 'Cute', 'Mini-game collection.', 'Compete with Tama and friends in various events.', 'A cute Japanese exclusive based on the cat anime.', 'Tamalympic features a series of fun and accessible sports challenges. It captures the heart of the series with adorable 8-bit sprites and lighthearted portable gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarot-no-yakata-japan', 'Game Gear', 'Tarot no Yakata (Japan)', '1994', 'Card', 'Sega', '1', 'Mystic', 'Tarot reading / Fortune telling.', 'Discover your future through the cards.', 'A unique Japanese digital fortune-telling title.', 'Tarot no Yakata allows you to perform virtual tarot readings. Featuring beautiful 8-bit artwork and multiple reading styles, it’s a curious and atmospheric piece of handheld software.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tarzan---lord-of-the-jungle-usa', 'Game Gear', 'Tarzan - Lord of the Jungle (USA)', '1994', 'Platform', 'Eurocom', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Save the jungle and your friends from hunters.', 'A rugged adventure starring the King of the Jungle.', 'Tarzan: Lord of the Jungle features climbing, swinging, and animal-based combat. Navigate lush 8-bit environments in this challenging and visually detailed handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tatakae!-pro-yakyuu-twin-league-japan', 'Game Gear', 'Tatakae! Pro Yakyuu Twin League (Japan)', '1992', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to victory in the dual-league tour.', 'A quirky and fast-paced Japanese baseball sim.', 'Tatakae! Pro Yakyuu Twin League features "chibi" style players and high-energy arcade action. It’s an accessible and fun sports title that makes great use of the system''s color.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-in-escape-from-mars-usa-europe', 'Game Gear', 'Taz in Escape from Mars (USA, Europe)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Escape from the Martian zoo and return to Earth.', 'A frantic and colorful Looney Tunes adventure.', 'Taz in Escape from Mars features the Tasmanian Devil''s signature spin. Bust through destructible environments in this visually impressive and high-speed 8-bit handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania---the-search-for-the-lost-seabirds-usa-europe', 'Game Gear', 'Taz-Mania - The Search for the Lost Seabirds (USA, Europe)', '1992', 'Platform', 'Teeny Weeny Games', '1', 'Cartoon', 'Side-scrolling platformer.', 'Search for the lost birds across the Tasmanian island.', 'A high-energy chase through diverse environments.', 'Taz-Mania features Taz in a quest filled with obstacles and enemies. Eat everything in sight and use your spin to survive this vibrant and difficult 8-bit portable classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tempo-jr-usa-europe', 'Game Gear', 'Tempo Jr. (USA, Europe)', '1995', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate the musical world and save the show.', 'A visually stunning spinoff of the 32X cult classic.', 'Tempo Jr. is one of the best-looking games on the system. Featuring incredible animation and catchy music, guide the grasshopper through rhythmic levels in this creative 8-bit gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tengen-world-cup-soccer-usa-europe', 'Game Gear', 'Tengen World Cup Soccer (USA, Europe)', '1994', 'Sports', 'Tengen', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the World Cup with your favorite national team.', 'A professional and licensed international soccer sim.', 'Tengen World Cup Soccer features smooth isometric gameplay and strategic team management. Experience the tension of the global tournament in this polished and competitive 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-usa-europe', 'Game Gear', 'Terminator 2 - Judgment Day (USA, Europe)', '1993', 'Action', 'Probe Software', '1', 'Sci-Fi', 'Side-scrolling action.', 'Protect John Connor and stop the T-1000.', 'A high-stakes action game based on the sci-fi sequel.', 'Terminator 2: Judgment Day features intense gunplay and driving sequences. Fight through the post-apocalyptic future and modern-day LA in this challenging and visually gritty 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-usa-europe', 'Game Gear', 'Terminator, The (USA, Europe)', '1991', 'Action', 'Probe Software', '1', 'Sci-Fi', 'Side-scrolling action.', 'Survive the machines and destroy Skynet.', 'A cinematic action title based on the original film.', 'The Terminator tasks you with navigating dangerous levels as Kyle Reese. With its dark atmosphere and impressive 8-bit soundtrack, it captures the tension of the classic sci-fi thriller perfectly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tesserae-usa-europe', 'Game Gear', 'Tesserae (USA, Europe)', '1993', 'Puzzle', 'Bullet-Proof Software', '2', 'Abstract', 'Mosaic puzzle.', 'Clear the board by flipping and matching tiles.', 'A complex and rewarding logic-based puzzle game.', 'Tesserae is a unique brain-teaser that requires deep strategy. Match colors and shapes to simplify the board in this sophisticated 8-bit handheld title, perfect for long puzzle sessions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tintin-in-tibet-europe-enfrdeesnlsv', 'Game Gear', 'Tintin in Tibet (Europe) (En,Fr,De,Es,Nl,Sv)', '1995', 'Platform', 'Bit Managers', '1', 'Adventure', 'Side-scrolling adventure.', 'Find your friend Tchang in the Himalayas.', 'A visually stunning European exclusive comic adventure.', 'Tintin in Tibet features incredible animation and faithful comic-book art. Navigate snowy peaks and solve environmental puzzles in this high-quality and difficult 8-bit handheld quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-and-jerry---the-movie-usa-europe', 'Game Gear', 'Tom and Jerry - The Movie (USA, Europe)', '1992', 'Platform', 'Hi Tech Expressions', '1', 'Cartoon', 'Side-scrolling platformer.', 'Chase each other through the city and the theater.', 'A colorful cat-and-mouse chase based on the movie.', 'Tom and Jerry: The Movie features vibrant graphics and frantic platforming. Use household items and quick reflexes to outsmart your rival in this charming and polished 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('torarete-tamaruka-japan', 'Game Gear', 'Torarete Tamaruka (Japan)', '1993', 'Action', 'Sega', '1', 'Fantasy', 'Photography / Simulation.', 'Take the best photos to win the competition.', 'A quirky Japanese exclusive photography sim.', 'Torarete Tamaruka is a unique title where timing and framing are key. Capture the perfect shot of elusive subjects in this creative and visually distinct 8-bit handheld experiment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('true-lies-usa-europe', 'Game Gear', 'True Lies (USA, Europe)', '1994', 'Action', 'Beam Software', '1', 'Military', 'Isometric action.', 'Stop the terrorist plot and rescue your family.', 'A high-octane shooter based on the Arnold hit.', 'True Lies features intense top-down gunplay and massive levels. Use a variety of weapons and tactical movement to clear enemy bases in this technically impressive and difficult 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-soccer-japan-europe-enfrdeesit', 'Game Gear', 'Ultimate Soccer (Japan, Europe) (En,Fr,De,Es,It)', '1993', 'Sports', 'Bit Managers', '2', 'Soccer', 'Sports simulation (Soccer).', 'Lead your nation to the world championship.', 'A fast-paced and fluid 8-bit soccer simulation.', 'Ultimate Soccer features smooth animation and multiple camera angles. Master the "after-touch" mechanics to curve your shots in this highly-regarded and competitive handheld sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('urban-strike-usa-europe', 'Game Gear', 'Urban Strike (USA, Europe)', '1994', 'Action', 'Granite Bay Software', '1', 'Military', 'Isometric vehicular shooter.', 'Stop the rogue industrialist from his orbital attack.', 'The final, refined entry in the Strike series.', 'Urban Strike brings the helicopter action to the city. Featuring on-foot missions and intense aerial combat, it’s a technical showcase of pseudo-3D destruction on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vampire---master-of-darkness-usa-europe', 'Game Gear', 'Vampire - Master of Darkness (USA, Europe)', '1992', 'Action', 'Sims', '1', 'Horror', 'Side-scrolling action.', 'Hunt Dracula through the streets of London.', 'Sega’s incredible answer to the Castlevania series.', 'Vampire: Master of Darkness is a gothic masterpiece. Use daggers, canes, and magic to battle supernatural foes in this atmospheric and high-quality 8-bit action-platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtua-fighter-animation-usa', 'Game Gear', 'Virtua Fighter Animation (USA)', '1994', 'Action', 'Sega', '1', 'Arcade', 'One-on-one fighting game.', 'Win the tournament to prove you are the best.', 'A stunning 8-bit recreation of the 3D fighter.', 'Virtua Fighter Animation features massive, fluidly animated sprites and technical combat. Based on the anime, it’s one of the most impressive fighting games ever released for a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtua-fighter-mini-japan', 'Game Gear', 'Virtua Fighter Mini (Japan)', '1994', 'Fighting', 'Sega AM2', '1', 'Arcade', 'One-on-one fighting game.', 'Master the martial arts and defeat your rivals.', 'The Japanese version of the 8-bit Virtua Fighter.', 'Virtua Fighter Mini captures the soul of the arcade original. Featuring the iconic roster and a surprisingly deep move list, it’s a must-play for fans of technical fighting games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vr-troopers-usa-europe', 'Game Gear', 'VR Troopers (USA, Europe)', '1995', 'Action', 'Sega', '1', 'Sci-Fi', 'One-on-one fighting game.', 'Stop Grimlord and his virtual army.', 'A martial arts brawler based on the live-action show.', 'VR Troopers features large character sprites and special moves. Battle through the virtual world to protect reality in this colorful and action-packed 8-bit handheld fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-land-japan', 'Game Gear', 'Wagan Land (Japan)', '1995', 'Platform', 'Sunsoft', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use your shout to stun enemies and reach the goal.', 'A charming Japanese exclusive with unique mechanics.', 'Wagan Land features a cute dragon whose primary weapon is his voice. Solve word puzzles and navigate creative levels in this vibrant and family-friendly 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune-usa-europe', 'Game Gear', 'Wheel of Fortune (USA, Europe)', '1993', 'Quiz', 'GameTek', '2', 'TV Game', 'Quiz / Trivia.', 'Spin the wheel and solve the word puzzles.', 'A faithful handheld version of the hit TV show.', 'Wheel of Fortune brings the game show excitement to your pocket. Featuring thousands of puzzles and the iconic wheel, it’s a perfect title for casual brain-training on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wimbledon-japan-europe', 'Game Gear', 'Wimbledon (Japan, Europe)', '1992', 'Sports', 'Sims', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the Grand Slam on the grass of Wimbledon.', 'A professional and challenging 8-bit tennis sim.', 'Wimbledon features fast-paced volleys and realistic court physics. Compete in singles or doubles and climb the rankings in this polished and competitive handheld sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-olympics---lillehammer-94-japan-enfrdeesitptsvno', 'Game Gear', 'Winter Olympics - Lillehammer ''94 (Japan) (En,Fr,De,Es,It,Pt,Sv,No)', '1994', 'Sports', 'Sega', '2', 'Simulation', 'Multi-event sports simulation.', 'Win the gold in the snowy mountains of Norway.', 'The Japanese edition of the winter sports hit.', 'Winter Olympics ''94 features events like bobsleigh and slalom. Master the precision controls and speed required to win in this detailed and atmospheric 8-bit sports collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-olympics---lillehammer-94-usa-europe-enfrdeesitptsvno', 'Game Gear', 'Winter Olympics - Lillehammer ''94 (USA, Europe) (En,Fr,De,Es,It,Pt,Sv,No)', '1994', 'Sports', 'Sega', '2', 'Simulation', 'Multi-event sports simulation.', 'Win the gold in the snowy mountains of Norway.', 'The international release of the Lillehammer sim.', 'Experience the chill of the Winter Games on your Game Gear. With a variety of disciplines and a strong competitive edge, it’s a comprehensive 8-bit challenge for sports enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizard-pinball-europe', 'Game Gear', 'Wizard Pinball (Europe)', '1995', 'Pinball', 'Teque London', '1', 'Arcade', 'Pinball simulation.', 'Achieve the high score on the magical table.', 'A creative and colorful European pinball game.', 'Wizard Pinball features a fantasy-themed table with unique hazards and bonuses. It offers solid 8-bit physics and addictive "one-more-go" gameplay for puzzle and arcade fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfchild-usa-europe', 'Game Gear', 'Wolfchild (USA, Europe)', '1992', 'Platform', 'Core Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use your mutant powers to stop the evil Chimera.', 'A dark and visually stunning action-platformer.', 'Wolfchild features incredible animation and a unique transformation system. Change into a powerful wolf-man to tear through enemies in this polished and atmospheric 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy---the-dragons-trap-usa-europe', 'Game Gear', 'Wonder Boy - The Dragon''s Trap (USA, Europe)', '1992', 'Action', 'West One', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Break the dragon''s curse to regain your humanity.', 'A legendary masterpiece of 8-bit non-linear design.', 'Wonder Boy: The Dragon''s Trap is widely considered one of the best games of the era. Explore a vast world and transform into different animals to unlock new areas in this epic quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-europe', 'Game Gear', 'Wonder Boy (Europe)', '1991', 'Platform', 'Escape', '1', 'Arcade', 'Side-scrolling platformer.', 'Rescue your girlfriend from the tribal king.', 'The vibrant handheld port of the arcade classic.', 'Wonder Boy (Europe) features the iconic skateboard and axe-throwing action. Navigate through forest and island levels in this colorful and fast-paced 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-japan', 'Game Gear', 'Wonder Boy (Japan)', '1991', 'Platform', 'Escape', '1', 'Arcade', 'Side-scrolling platformer.', 'Rescue your girlfriend from the tribal king.', 'The original Japanese version of the arcade hit.', 'Experience the charm of Wonder Boy on the move. With its catchy music and challenging platforming, this 8-bit version is a perfect conversion of the Sega arcade legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-iii---the-dragons-trap-usa-europe-beta', 'Game Gear', 'Wonder Boy III - The Dragon''s Trap (USA, Europe) (Beta)', '1992', 'Platform', 'West One', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Break the dragon''s curse to regain your humanity.', 'A rare beta version of the legendary RPG sequel.', 'This Dragon''s Trap Beta offers a look at the development of the 8-bit masterpiece. Test the transformation mechanics and early level layouts in this foundational build of the classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('woody-pop-usa-europe', 'Game Gear', 'Woody Pop (USA, Europe)', '1991', 'Puzzle', 'Sega', '1', 'Cute', 'Breakout / Arkanoid.', 'Clear the blocks using your paddle and ball.', 'A polished and creative block-breaking puzzle.', 'Woody Pop features unique level branching and power-ups. Guide your paddle through dozens of screens in this colorful and addictive 8-bit take on the breakout genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('woody-pop-usa-europe-v11', 'Game Gear', 'Woody Pop (USA, Europe) (v1.1)', '1991', 'Puzzle', 'Sega', '1', 'Cute', 'Breakout / Arkanoid.', 'Clear the blocks using your paddle and ball.', 'Refined v1.1 of the block-breaking classic.', 'This v1.1 of Woody Pop features improved ball physics and minor balance tweaks. It’s the definitive way to play this charming and high-energy 8-bit handheld puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-class-leader-board-usa', 'Game Gear', 'World Class Leader Board (USA)', '1991', 'Sports', 'U.S. Gold', '1', 'Golf', 'Sports simulation (Golf).', 'Win the championship with professional precision.', 'A high-quality and technical 8-bit golf sim.', 'World Class Leader Board features realistic wind and power mechanics. Compete on world-renowned courses in this detailed and strategically deep portable golf experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-usa-94-usa-europe-enfrdeesitnlptsv', 'Game Gear', 'World Cup USA 94 (USA, Europe) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1994', 'Sports', 'U.S. Gold', '2', 'Soccer', 'Sports simulation (Soccer).', 'Lead your team to the 1994 World Cup trophy.', 'The officially licensed tournament simulation.', 'World Cup USA 94 features all the teams, stadiums, and the official mascot. Experience the heat of the international stage in this polished and feature-rich 8-bit soccer title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-derby-japan', 'Game Gear', 'World Derby (Japan)', '1994', 'Racing', 'Sega', '1', 'Horse Racing', 'Sports simulation (Horse Racing).', 'Bet and race your way to the championship.', 'A detailed Japanese exclusive horse racing sim.', 'World Derby combines management and action. Breed your horses and compete in high-stakes races in this deep and visually impressive 8-bit handheld sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-series-baseball-95-usa-europe', 'Game Gear', 'World Series Baseball ''95 (USA, Europe)', '1995', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Lead your team to victory in the ''95 season.', 'The refined sequel to the hit baseball series.', 'World Series Baseball ''95 features updated rosters and improved gameplay mechanics. With multiple camera angles and smooth batting, it’s one of the most polished sports simulations on the Game Gear.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-series-baseball-usa-europe', 'Game Gear', 'World Series Baseball (USA, Europe)', '1993', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the World Series with professional teams.', 'A high-quality and licensed 8-bit baseball sim.', 'World Series Baseball brings the diamond to your pocket. Featuring real players and deep stats, it offers a realistic and competitive baseball experience that looks great on the color screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-series-baseball-usa-europe-v11', 'Game Gear', 'World Series Baseball (USA, Europe) (v1.1)', '1993', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the World Series with professional teams.', 'Updated v1.1 of the professional baseball sim.', 'This v1.1 release of World Series Baseball features minor balance tweaks and bug fixes. Experience the pressure of the MLB with refined 8-bit physics and smooth handheld controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-raw-usa-europe', 'Game Gear', 'WWF Raw (USA, Europe)', '1994', 'Fighting', 'Acclaim', '2', 'Wrestling', 'One-on-one wrestling.', 'Defeat your rivals to become the WWF Champion.', 'Gritty and hard-hitting 8-bit wrestling action.', 'WWF Raw features iconic superstars like Undertaker and Bret Hart. Master a variety of moves and signature finishers in this high-energy handheld brawler with multiple match types.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania-steel-cage-challenge-europe', 'Game Gear', 'WWF Wrestlemania Steel Cage Challenge (Europe)', '1992', 'Fighting', 'Sims', '2', 'Wrestling', 'One-on-one wrestling.', 'Escape the cage or pin your opponent to win.', 'A unique steel cage wrestling experience.', 'Wrestlemania Steel Cage Challenge brings the intensity of the squared circle to the Game Gear. Use the cage to your advantage in this tactical and action-packed European exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---gamemasters-legacy-usa-europe', 'Game Gear', 'X-Men - Gamemaster''s Legacy (USA, Europe)', '1995', 'Action', 'Sega', '1', 'Superhero', 'Side-scrolling action platformer.', 'Stop the Gamemaster and save the captured X-Men.', 'A deep and challenging Marvel superhero quest.', 'Gamemaster''s Legacy features multiple playable X-Men with unique powers. Switch between heroes to navigate complex levels and defeat iconic villains in this polished 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---mojo-world-usa-europe', 'Game Gear', 'X-Men - Mojo World (USA, Europe)', '1994', 'Action', 'Sega', '1', 'Superhero', 'Side-scrolling action platformer.', 'Escape Mojo World and defeat the spineless One.', 'A vibrant and difficult X-Men adventure.', 'X-Men: Mojo World lets you control Wolverine and Rogue in a fight for survival. Use mutant abilities to solve environmental puzzles and battle bosses in this visually impressive 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men-usa-europe', 'Game Gear', 'X-Men (USA, Europe)', '1993', 'Action', 'Sega', '1', 'Superhero', 'Side-scrolling action.', 'Defeat Magneto and his army of mutants.', 'The debut of the X-Men on Sega''s handheld.', 'Experience the power of the X-Men on the go. Featuring Storm, Wolverine, and Cyclops, this action-packed title delivers intense platforming and combat across iconic Marvel locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yogi-bear-in-yogi-bears-goldrush-proto', 'Game Gear', 'Yogi Bear in Yogi Bear''s Goldrush (Proto)', '1994', 'Platform', 'Homebrew', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect the gold and avoid the park rangers.', 'An unreleased prototype starring the famous bear.', 'Yogi Bear''s Goldrush (Proto) offers a rare look at a lost handheld title. Explore Jellystone Park in this colorful and family-friendly 8-bit platformer with classic mascot gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-yu-hakusho---horobishimono-no-gyakushuu-japan', 'Game Gear', 'Yu Yu Hakusho - Horobishimono no Gyakushuu (Japan)', '1994', 'Fighting', 'Tom Create', '2', 'Anime', 'One-on-one fighting game.', 'Win the tournament using spiritual powers.', 'A high-energy fighter based on the hit anime.', 'Yu Yu Hakusho features large sprites and fluid combat. Use Yusuke''s Spirit Gun and other signature moves to defeat powerful rivals in this technically impressive Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-yu-hakusho-2---gekitou!-nanakyou-no-tatakai-japan', 'Game Gear', 'Yu Yu Hakusho 2 - Gekitou! Nanakyou no Tatakai (Japan)', '1994', 'Fighting', 'Tom Create', '2', 'Anime', 'One-on-one fighting game.', 'Defeat the seven powerful rivals in combat.', 'The refined and faster sequel to the anime fighter.', 'Yu Yu Hakusho 2 improves on everything from the first game, featuring a larger roster and more special moves. It is one of the best-looking and best-playing 1v1 brawlers on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('yu-yu-hakusho-2---gekitou!-nanakyou-no-tatakai-japan-en-by-gaijin-v10', 'Game Gear', 'Yu Yu Hakusho 2 - Gekitou! Nanakyou no Tatakai (Japan) [En by Gaijin v1.0]', '1994', 'Fighting', 'Tom Create', '2', 'Anime', 'One-on-one fighting game.', 'Defeat the seven powerful rivals in combat.', 'English fan-translated version of the anime sequel.', 'This localized version of Yu Yu Hakusho 2 allows Western fans to understand the story and move lists of this incredible handheld fighter, making the deep combat mechanics fully accessible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zan-gear-japan', 'Game Gear', 'Zan Gear (Japan)', '1995', 'Action', 'Sega', '1', 'Mecha', 'Turn-based strategy.', 'Command your units to conquer the enemy territory.', 'A Japanese exclusive futuristic military sim.', 'Zan Gear features tactical grid-based combat with a variety of land and air units. It’s a deep and rewarding strategy title that rewards patience and careful planning on the 8-bit screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool-usa', 'Game Gear', 'Zool (USA)', '1993', 'Platform', 'Gremlin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the Nth dimension from the alien invaders.', 'A fast and fluid port of the ninja-gremlin hit.', 'Zool features lightning-fast gameplay and vibrant, candy-themed levels. Use your ninja skills to climb and shoot through this high-energy and challenging 8-bit arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool-no-yume-bouken-japan', 'Game Gear', 'Zool no Yume Bouken (Japan)', '1994', 'Platform', 'Gremlin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the Nth dimension from the alien invaders.', 'The original Japanese release of the Zool adventure.', 'Zool no Yume Bouken (Zool''s Dream Adventure) brings the cult-classic mascot to the Game Gear with smooth animation and catchy 8-bit music. It’s a technical showcase for the handheld''s speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop-europe', 'Game Gear', 'Zoop (Europe)', '1995', 'Puzzle', 'Hooked Game Design', '1', 'Arcade', 'Tile-matching puzzle.', 'Shoot shapes from the center to clear the edges.', 'A frantic and colorful European-exclusive puzzler.', 'Zoop (Europe) is a game of quick reflexes and spatial logic. Clear the encroaching tiles before they reach the center in this addictive and unique 8-bit handheld puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zoop-usa', 'Game Gear', 'Zoop (USA)', '1995', 'Puzzle', 'Hooked Game Design', '1', 'Arcade', 'Tile-matching puzzle.', 'Shoot shapes from the center to clear the edges.', 'The North American release of the puzzle sensation.', 'Experience the "America''s Largest Puzzle Game" on your Game Gear. Zoop offers endless replayability and increasing difficulty, making it a perfect title for short bursts of portable play.');